const data = $input.first().json;
const event = data.event_type;
const crmConfig = data.tenant_config.crm;
const payload = data.payload;

// Map event types to CRM record types
const recordTypeMap = {
  trial_signup: "Lead",
  upgrade: "Opportunity",
  churn_signal: "Case"
};

const recordType = crmConfig.record_type || recordTypeMap[event] || "Lead";

const crmRecord = {
  record_type: recordType,
  event_type: event,
  contact_email: payload.customer_email,
  tenant_id: data.tenant_config.tenant_id,
  properties: {
    source: "oem-platform",
    event_timestamp: new Date().toISOString(),
    ...payload
  }
};

if (!crmRecord.contact_email) {
  throw new Error(`No contact email in payload for CRM record on tenant: ${data.tenant_config.tenant_id}`);
}

return [{
  json: {
    ...data,
    crm_record: crmRecord
  }
}];

